(* [comment removed for export] *)
Definition kfin_post (kfr n S1 : Z) (x72 : word) (ra sp gp tp t0 t1 t2 s0 a3 a5 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F0 : bvmap 5 word) (m0 : mem) : machine_state -> Prop :=
  fun ms' => exists (a1' a2' a6' a7' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 S1) (Z_to_bv 64 kfr) a1' a2' a3 (Z_to_bv 64 n) a5 a6' a7'
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F' (Z_to_bv 64 0xc3678) fc' None m' (seg_rom asegs)
    /\ fs_agree F0 F' /\ frm0 fc' /\ munch [(kfr, kfr + 1024); (S1 + 72, S1 + 80)] m0 m' /\ wmono asegs m0 m' /\ mem_inv asegs m'
    /\ rw_cells asegs m' (S1 + 72) [C8 x72] /\ wr_at asegs m' kfr 1024 /\ acc asegs m' kfr 1024.

Lemma kfr_inner : forall (j : nat) (i n : Z)
    (ra sp gp tp t0 t1 t2 s0 a3 a5 a6 a7 s2 s3 s4 s5 s6 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F0 F : bvmap 5 word) (fc : bv 32) (m0 m : mem) (kfr S1 : Z) (x72 : word),
  Z.of_nat j = n - i -> 0 <= i < n -> n <= 255 ->
  0 < kfr -> kfr mod 16 = 0 -> kfr + 1024 <= 2^47 -> (kfr + 1024 <= 0x7fff7000 \/ 0x10007fff8000 <= kfr) ->
  0 <= S1 -> S1 + 160 <= 2^47 -> (S1 + 160 <= kfr \/ kfr + 1024 <= S1) ->
  fs_agree F0 F -> reg_get F (15%bv : bv 5) = fcvt_s_w RNE (Z_to_bv 64 n) -> frm0 fc ->
  munch [(kfr, kfr + 1024); (S1 + 72, S1 + 80)] m0 m -> wmono asegs m0 m ->
  rw_cells asegs m (S1 + 72) [C8 x72] -> wr_at asegs m kfr 1024 -> acc asegs m kfr 1024 -> mem_inv asegs m ->
  evt asegs (kfin_post kfr n S1 x72 ra sp gp tp t0 t1 t2 s0 a3 a5 s2 s3 s4 s5 s6 (Z_to_bv 64 2147450880) s8 s9 s10 s11 t3 t4 t5 t6 F0 m0)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 S1) (Z_to_bv 64 kfr) (Z_to_bv 64 (kfr + 4 * i)) (Z_to_bv 64 (kfr + 4 * i)) a3 (Z_to_bv 64 i) a5 a6 a7
             s2 s3 s4 s5 s6 (Z_to_bv 64 2147450880) s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xc3630) fc None m (seg_rom asegs)).
