(* [comment removed for export] *)
Definition kfr_post (kfr maxval S1 : Z) (x72 : word) (ra sp gp tp t1 t2 s0 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F0 : bvmap 5 word) (m0 : mem) : machine_state -> Prop :=
  fun ms' => exists (a1' a2' a4' a5' a6' a7' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem),
    ms' = MS (mkR ra sp gp tp (Z_to_bv 64 11) t1 t2 s0 (Z_to_bv 64 S1) (Z_to_bv 64 kfr) a1' a2' (Z_to_bv 64 maxval) a4' a5' a6' a7'
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F' (Z_to_bv 64 0xc2c4c) fc' None m' (seg_rom asegs)
    /\ fs_agree F0 F' /\ frm0 fc' /\ munch [(kfr, kfr + 1024); (S1 + 72, S1 + 80)] m0 m' /\ wmono asegs m0 m' /\ mem_inv asegs m'
    /\ rw_cells asegs m' (S1 + 72) [C8 x72] /\ wr_at asegs m' kfr 1024 /\ acc asegs m' kfr 1024.

(* [comment removed for export] *)
Lemma kfr_latch : forall (i k : Z)
    (ra sp gp tp t1 t2 s0 a1 a2 a6 a7 s2 s3 s5 s6 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F0 F : bvmap 5 word) (fc : bv 32) (m0 m : mem) (kfr S1 maxval : Z) (x72 : word),
  0 <= k <= 8 -> 0 <= i <= 255 -> 0 <= maxval <= 255 ->
  fs_agree F0 F -> frm0 fc ->
  munch [(kfr, kfr + 1024); (S1 + 72, S1 + 80)] m0 m -> wmono asegs m0 m ->
  rw_cells asegs m (S1 + 72) [C8 x72] -> wr_at asegs m kfr 1024 -> acc asegs m kfr 1024 -> mem_inv asegs m ->
  (k + 1 < 9 -> i <= maxval -> forall (a1' a2' a6' a7' : word),
     evt asegs (kfr_post kfr maxval S1 x72 ra sp gp tp t1 t2 s0 s2 s3 (Z_to_bv 64 9) s5 s6 (Z_to_bv 64 2147450880) s8 s9 s10 s11 t3 t4 t5 t6 F0 m0)
       (MS (mkR ra sp gp tp (Z_to_bv 64 11) t1 t2 s0 (Z_to_bv 64 S1) (Z_to_bv 64 kfr) a1' a2' (Z_to_bv 64 maxval) (Z_to_bv 64 i) (Z_to_bv 64 (k + 1)) a6' a7'
                s2 s3 (Z_to_bv 64 9) s5 s6 (Z_to_bv 64 2147450880) s8 s9 s10 s11 t3 t4 t5 t6)
           F (Z_to_bv 64 0xc35d0) fc None m (seg_rom asegs))) ->
  evt asegs (kfr_post kfr maxval S1 x72 ra sp gp tp t1 t2 s0 s2 s3 (Z_to_bv 64 9) s5 s6 (Z_to_bv 64 2147450880) s8 s9 s10 s11 t3 t4 t5 t6 F0 m0)
    (MS (mkR ra sp gp tp (Z_to_bv 64 11) t1 t2 s0 (Z_to_bv 64 S1) (Z_to_bv 64 kfr) a1 a2 (Z_to_bv 64 maxval) (Z_to_bv 64 i) (Z_to_bv 64 (k + 1)) a6 a7
             s2 s3 (Z_to_bv 64 9) s5 s6 (Z_to_bv 64 2147450880) s8 s9 s10 s11 t3 t4 t5 t6)
