(* [comment removed for export] *)
Lemma kfr_outer : forall (j : nat) (i k : Z)
    (ra sp gp tp t1 t2 s0 a1 a2 a6 a7 s2 s5 s6 s8 s9 s10 t3 t4 t5 t6 : word)
    (F0 F : bvmap 5 word) (fc : bv 32) (m0 m : mem) (kfr nc pmin pmax minval maxval S1 : Z) (ncs : list word) (x72 : word),
  Z.of_nat j = 9 - k -> 0 <= k <= 8 -> 0 <= i <= maxval ->
  0 < kfr -> kfr mod 16 = 0 -> kfr + 1024 <= 2^47 -> (kfr + 1024 <= 0x7fff7000 \/ 0x10007fff8000 <= kfr) ->
  0 < nc -> nc mod 16 = 0 -> nc + 40 <= 2^47 -> (nc + 40 <= 0x7fff7000 \/ 0x10007fff8000 <= nc) ->
  0 <= minval <= 255 -> 0 <= maxval <= 255 -> length ncs = 10%nat -> Forall (fun w => 0 <= bv_unsigned w <= 255) ncs ->
  0 <= S1 -> S1 + 160 <= 2^47 -> (S1 + 160 <= kfr \/ kfr + 1024 <= S1) ->
  (forall m', munch [(kfr, kfr + 1024); (S1 + 72, S1 + 80)] m0 m' -> wmono asegs m0 m' -> bc_karr_ro pmin pmax minval maxval nc ncs (S1 + 128) 11 m') ->
  fs_agree F0 F -> frm0 fc ->
  munch [(kfr, kfr + 1024); (S1 + 72, S1 + 80)] m0 m -> wmono asegs m0 m ->
  rw_cells asegs m (S1 + 72) [C8 x72] -> wr_at asegs m kfr 1024 -> acc asegs m kfr 1024 -> mem_inv asegs m ->
  evt asegs (kfr_post kfr maxval S1 x72 ra sp gp tp t1 t2 s0 s2 (Z_to_bv 64 pmax) (Z_to_bv 64 9) s5 s6 (Z_to_bv 64 2147450880) s8 s9 s10
                      (Z_to_bv 64 nc) t3 t4 t5 t6 F0 m0)
    (MS (mkR ra sp gp tp (Z_to_bv 64 11) t1 t2 s0 (Z_to_bv 64 S1) (Z_to_bv 64 kfr) a1 a2 (Z_to_bv 64 maxval) (Z_to_bv 64 i) (Z_to_bv 64 k) a6 a7
             s2 (Z_to_bv 64 pmax) (Z_to_bv 64 9) s5 s6 (Z_to_bv 64 2147450880) s8 s9 s10 (Z_to_bv 64 nc) t3 t4 t5 t6)
